# ============================================================================================ build
def texts(b):
    k = b[0]
    if k in ("p", "p0", "fig"):
        return [b[1]] if k != "fig" else [b[2]]
    if k == "table":
        return [b[1]] + list(b[2]) + [c for r in b[3] for c in r]
    return []


def build(path, author=True):
    cit = E.Citations(LIB)
    for b in B:
        for t in texts(b):
            cit.scan(t)
    doc = E.Doc(cit)
    for b in B:
        k = b[0]
        if k == "title":
            doc.title(b[1])
        elif k == "author":
            if author:
                doc.centered(b[1], 22)
        elif k == "small":
            if author:
                doc.centered(b[1], 19)
        elif k == "blank":
            doc.blank()
        elif k == "h1":
            doc.h1(b[1])
        elif k == "h2":
            doc.h2(b[1])
        elif k == "p":
            doc.p(b[1])
        elif k == "p0":
            doc.p(b[1], indent=False)
        elif k == "eq":
            doc.eq(b[1], b[2])
        elif k == "fig":
            doc.fig(os.path.join(FIG, b[1]), b[2], b[3])
        elif k == "table":
            doc.table(b[1], b[2], b[3], b[4] if len(b) > 4 else None)
        elif k == "refs":
            doc.h1("References")
            doc.refs(cit.entries())
    doc.save(path)
    return cit


if __name__ == "__main__":
    os.makedirs(OUT, exist_ok=True)
    c = build(os.path.join(OUT, "FMI_Hybrid_Liquid_Loading_Estimation_v6.docx"))
    build(os.path.join(OUT, "FMI_Hybrid_Liquid_Loading_Estimation_v6_no_author_block.docx"), author=False)
    print("built v6; %d references" % len(c.order))
